def stairs(n):
    prev, cur = 1, 1                 # ways(0), ways(1)
    for _ in range(2, n + 1):
        prev, cur = cur, prev + cur
    return cur


def min_coins(coins, amount):
    INF = float('inf')
    best = [0] + [INF] * amount      # best[0] = 0: no coins for nothing
    for a in range(1, amount + 1):   # bottom up: smaller amounts first
        for c in coins:
            if c <= a and best[a - c] + 1 < best[a]:
                best[a] = best[a - c] + 1
    return best[amount] if best[amount] < INF else -1
